#!/usr/bin/env node
/* Rebuilds react/src/icons/index.ts from the components directory — same
   rule as generate-icon-registry.mjs: the directory is the source of truth. */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
const root = path.join(path.dirname(fileURLToPath(import.meta.url)), "..");
const dir = path.join(root, "react/src/icons/components");
const names = fs
  .readdirSync(dir)
  .filter((f) => f.endsWith(".tsx"))
  .map((f) => f.replace(/\.tsx$/, ""))
  .sort();
const lines = [
  "// GENERATED by scripts/generate-icons-index.mjs — do not edit by hand.",
  ...names.map((n) => `export * from "./components/${n}";`),
  "",
];
fs.writeFileSync(path.join(root, "react/src/icons/index.ts"), lines.join("\n"));
console.log(`Wrote react/src/icons/index.ts (${names.length} files)`);
